/*
 * Whitelist mode (same approach as arktsbase.version / arktsassembler.version):
 * only the symbols matching the patterns below are exported; everything else
 * (std:: / vixl / asmjit / securec / CRT entry points, ark::base template
 * leaks) is hidden by the `local: *` fallback, so new internal symbols can
 * not leak into .dynsym unnoticed.
 *
 * Exported surface: the ark::compiler encoder API — Encoder with its arch
 * backends (a mid-name `*` spans nested namespaces and template arguments),
 * the target.cpp factories, their RTTI families, and the only free function
 * defined here, BackendSupport (type_info.h, target.cpp). libarktscompiler
 * compiles encode.cpp itself but localizes its copy; this library is the sole
 * process-wide exporter of the API for it, paoc, aotdump, irtoc and the
 * runtime_library_exports_test contract.
 */
{
  global:
    extern "C++" {
      ark::compiler::*Encoder*;
      ark::compiler::*LabelHolder*;
      ark::compiler::AssemblyPrinter*;
      ark::compiler::RegistersDescription*;
      ark::compiler::*RegisterDescription*;
      ark::compiler::*CallingConvention*;
      ark::compiler::*ParameterInfo*;
      ark::compiler::CallConv*;
      ark::compiler::BackendSupport*;
      vtable?for?ark::compiler::*;
      VTT?for?ark::compiler::*;
      typeinfo?for?ark::compiler::*;
      typeinfo?name?for?ark::compiler::*;
      construction?vtable?for?ark::compiler::*;
      guard?variable?for?ark::compiler::*;
      virtual?thunk?to?ark::compiler::*;
      non?virtual?thunk?to?ark::compiler::*;
    };
  local:
    *;
};
